	llm := &scripted{f: fs, repeatSearchOnce: true}
	out, err := New(Config{Timeout: 90 * time.Second}, llm, fakeConnector{fs}).Ask(context.Background(), "full")
	if err != nil {
		t.Fatal(err)
	}
	if !llm.repeatedSearchSent || out.Content != "done" {
