	if err != nil {
		t.Fatalf("Ask() error = %v", err)
	}
	if session.name != "get_github_repository" || session.arguments["owner"] != "modelcontextprotocol" || session.arguments["repository"] != "go-sdk" {
		t.Fatalf("tool call = %q %#v", session.name, session.arguments)
	}
