func Summarize(input domain.SummarizeInput) (domain.SummarizeOutput, error) {
	input.Query = cleanSpace(input.Query)
	if input.Query == "" || len([]rune(input.Query)) > 300 {
		return domain.SummarizeOutput{}, errors.New("query must contain 1 to 300 characters")
	}
	if input.MaxSentences < 1 || input.MaxSentences > 10 {
		return domain.SummarizeOutput{}, errors.New("max_sentences must be between 1 and 10")
	}
	if len(input.Documents) > 5 {
		return domain.SummarizeOutput{}, errors.New("documents must contain at most 5 items")
	}
	terms := meaningfulWords(input.Query)
	seen := map[string]bool{}
	all := make([]rankedSentence, 0)
	sources := make([]domain.Source, 0, len(input.Documents))
	seenSources := map[string]bool{}
	order := 0
	for _, document := range input.Documents {
		document.Title, document.URL, document.Text = cleanSpace(document.Title), strings.TrimSpace(document.URL), cleanSpace(document.Text)
		if document.URL != "" && !seenSources[document.URL] {
			sources = append(sources, domain.Source{Title: document.Title, URL: document.URL})
			seenSources[document.URL] = true
		}
		for _, match := range splitSentences(document.Text) {
			sentence := cleanSpace(match)
			key := strings.ToLower(strings.Trim(sentence, " .!?…"))
			if key == "" || seen[key] {
				continue
			}
			seen[key] = true
			words := meaningfulWords(sentence)
			score := len(words)
			for term := range terms {
				if words[term] {
					score += 12
				}
			}
			if len([]rune(sentence)) >= 45 && len([]rune(sentence)) <= 260 {
				score += 4
			}
			all = append(all, rankedSentence{text: sentence, order: order, score: score})
			order++
		}
	}
	warning := ""
	if len(all) == 0 {
		warning = "Недостаточно данных для составления сводки."
		return domain.SummarizeOutput{OK: true, Query: input.Query, Sources: sources, InputDocuments: len(input.Documents), Warning: warning}, nil
	}
	ranked := append([]rankedSentence(nil), all...)
	sort.SliceStable(ranked, func(i, j int) bool {
		if ranked[i].score == ranked[j].score {
			return ranked[i].order < ranked[j].order
		}
		return ranked[i].score > ranked[j].score
	})
	count := input.MaxSentences
	if len(ranked) < count {
		count = len(ranked)
		warning = "Доступно меньше информативных предложений, чем запрошено."
	}
	chosen := append([]rankedSentence(nil), ranked[:count]...)
	sort.Slice(chosen, func(i, j int) bool { return chosen[i].order < chosen[j].order })
	parts := make([]string, len(chosen))
	for i := range chosen {
		parts[i] = chosen[i].text
	}
	return domain.SummarizeOutput{OK: true, Query: input.Query, Summary: strings.Join(parts, " "), Sources: sources, InputDocuments: len(input.Documents), SentenceCount: len(chosen), Warning: warning}, nil
}

func TestAgentModelSelectedPipelineAndExactTransfer(t *testing.T) {
	a, llm, dir := testPipeline(t, false)
	result, err := a.Ask(context.Background(), "Найди MCP, сделай сводку и сохрани.")
	if err != nil {
		t.Fatal(err)
	}
	if llm.step != 4 || result.Content == "" {
		t.Fatalf("incomplete loop: step=%d response=%+v", llm.step, result)
	}
	var order, ids []string
	for _, event := range result.Trace {
		if event.Stage == "model/tool_call" {
			order = append(order, event.Tool)
			ids = append(ids, event.ToolCallID)
		}
	}
	if !reflect.DeepEqual(order, []string{pipeline.SearchToolName, pipeline.SummarizeToolName, pipeline.SaveToolName}) {
		t.Fatalf("order=%v", order)
	}
	if !reflect.DeepEqual(ids, []string{"call-search", "call-summary", "call-save"}) {
		t.Fatalf("ids=%v", ids)
	}
	path := filepath.Join(dir, "mcp-summary.md")
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	hash := fmt.Sprintf("%x", sha256.Sum256(data))
	var saved pipeline.SaveOutput
	for _, event := range result.Trace {
		if event.Stage == "mcp/tools/call" && event.Tool == pipeline.SaveToolName {
			encoded, _ := json.Marshal(event.Result)
			if err := json.Unmarshal(encoded, &saved); err != nil {
				t.Fatal(err)
			}
		}
	}
	if saved.SHA256 != hash || saved.Path != path {
		t.Fatalf("saved=%+v hash=%s", saved, hash)
	}
	// The summary result and save arguments must be byte-for-byte equal.
	var summary string
	var saveContent string
	for _, event := range result.Trace {
		if event.Stage == "mcp/tools/call" && event.Tool == pipeline.SummarizeToolName {
			encoded, _ := json.Marshal(event.Result)
			var out pipeline.SummarizeOutput
			_ = json.Unmarshal(encoded, &out)
			summary = out.Summary
		}
		if event.Stage == "model/tool_call" && event.Tool == pipeline.SaveToolName {
			saveContent, _ = event.Arguments["content"].(string)
		}
	}
	if summary == "" || saveContent != summary {
		t.Fatalf("summary transfer changed: %q != %q", saveContent, summary)
	}
}

func TestWikipediaClientAndSummarize(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Header.Get("User-Agent") == "" {
			t.Error("missing user agent")
		}
		_, _ = w.Write([]byte(`{"query":{"pages":[{"title":"MCP","fullurl":"https://en.wikipedia.org/wiki/MCP","extract":"MCP is a protocol. Dr. Smith described it. MCP connects tools."}]}}`))
	}))
	defer srv.Close()
	c := NewClient(srv.Client())
	c.BaseURL = srv.URL
	c.Now = func() time.Time { return time.Unix(1, 0) }
	out, err := c.Search(context.Background(), domain.SearchInput{Query: "MCP", Language: "en", Limit: 1})
	if err != nil || out.Count != 1 {
		t.Fatalf("out=%+v err=%v", out, err)
	}
	sum, err := Summarize(domain.SummarizeInput{Query: "MCP", Documents: out.Documents, MaxSentences: 2})
	if err != nil || sum.SentenceCount != 2 || !strings.Contains(sum.Summary, "MCP") {
		t.Fatalf("sum=%+v err=%v", sum, err)
	}
	again, _ := Summarize(domain.SummarizeInput{Query: "MCP", Documents: append(out.Documents, out.Documents...), MaxSentences: 3})
	if strings.Count(again.Summary, "MCP is a protocol") != 1 {
		t.Fatalf("duplicates not removed: %s", again.Summary)
	}
	parts := splitSentences("Dr. Smith wrote this. Т. е. граница сохранена.")
	if len(parts) != 2 || !strings.Contains(parts[0], "Dr. Smith") || !strings.Contains(parts[1], "Т. е.") {
		t.Fatalf("abbreviation split failed: %#v", parts)
	}
}

func (f *scriptedLLM) Complete(_ context.Context, request ChatRequest) (ChatResponse, error) {
	f.requests = append(f.requests, request)
	if request.ToolChoice != "auto" {
		f.t.Fatalf("tool_choice=%q", request.ToolChoice)
	}
	if len(request.Tools) != 3 {
		f.t.Fatalf("got %d tools", len(request.Tools))
	}
	call := func(id, name string, args any) ChatResponse {
		encoded, _ := json.Marshal(args)
		return ChatResponse{Choices: []Choice{{
			Message: Message{Role: "assistant", ToolCalls: []ToolCall{{
				ID: id, Type: "function", Function: ToolCallFunction{Name: name, Arguments: string(encoded)},
			}}},
			FinishReason: "tool_calls",
		}}}
	}
	switch f.step {
	case 0:
		f.step++
		return call("call-search", pipeline.SearchToolName, map[string]any{"query": "Model Context Protocol", "language": "en", "limit": 2}), nil
	case 1:
		if f.unknownSent {
			assertLastToolID(f.t, request.Messages, "call-summary-unknown")
		} else {
			assertLastToolID(f.t, request.Messages, "call-search")
		}
		if f.invalidOnce && !f.invalidSent {
			f.invalidSent = true
			return ChatResponse{Choices: []Choice{{Message: Message{Role: "assistant", ToolCalls: []ToolCall{{ID: "call-summary-broken", Type: "function", Function: ToolCallFunction{Name: pipeline.SummarizeToolName, Arguments: `{"query":"Model Context Protocol","documents":[`}}}}, FinishReason: "length"}}}, nil
		}
		if f.unknownOnce && !f.unknownSent {
			f.unknownSent = true
			documents := make([]map[string]any, len(f.documents))
			for i, document := range f.documents {
				documents[i] = map[string]any{"title": document.Title, "url": document.URL, "text": document.Text}
			}
			documents[0]["url_note"] = "for display only"
			return call("call-summary-unknown", pipeline.SummarizeToolName, map[string]any{"query": "Model Context Protocol", "documents": documents, "max_sentences": 2}), nil
		}
		docs := f.documents
		if f.corrupt {
			docs = []pipeline.Document{}
		}
		f.step++
		return call("call-summary", pipeline.SummarizeToolName, pipeline.SummarizeInput{Query: "Model Context Protocol", Documents: docs, MaxSentences: 2}), nil
	case 2:
		assertLastToolID(f.t, request.Messages, "call-summary")
		f.step++
		return call("call-save", pipeline.SaveToolName, pipeline.SaveInput{Filename: "mcp-summary.md", Query: f.summary.Query, Content: f.summary.Summary, Sources: f.summary.Sources}), nil
	case 3:
		assertLastToolID(f.t, request.Messages, "call-save")
		f.step++
		return ChatResponse{Choices: []Choice{{Message: Message{Role: "assistant", Content: "Готово: файл сохранён, путь и SHA-256 подтверждены."}, FinishReason: "stop"}}}, nil
	default:
		return ChatResponse{}, fmt.Errorf("unexpected model call")
	}
}

func TestSaveAtomicSHAAndMarkdown(t *testing.T) {
	dir := t.TempDir()
	fixed := time.Date(2026, 9, 27, 12, 0, 0, 0, time.UTC)
	saver := NewSaver(dir)
	saver.Now = func() time.Time { return fixed }
	target := filepath.Join(dir, "summary.md")
	if err := os.WriteFile(target, []byte("old"), 0o600); err != nil {
		t.Fatal(err)
	}
	result, err := saver.Save(SaveInput{Filename: "summary.md", Query: "MCP", Content: "Exact summary.", Sources: []Source{{Title: "Article", URL: "https://en.wikipedia.org/wiki/MCP"}}})
	if err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile(target)
	if err != nil {
		t.Fatal(err)
	}
	wantHash := fmt.Sprintf("%x", sha256.Sum256(data))
	if result.Path != target || result.SHA256 != wantHash || result.Bytes != int64(len(data)) {
		t.Fatalf("metadata mismatch: %+v", result)
	}
	text := string(data)
	for _, fragment := range []string{"# Сводка: MCP", "**Поисковый запрос:** MCP", "Exact summary.", "[Article](https://en.wikipedia.org/wiki/MCP)", fixed.Format(time.RFC3339)} {
		if !strings.Contains(text, fragment) {
			t.Errorf("missing %q", fragment)
		}
	}
	entries, _ := os.ReadDir(dir)
	if len(entries) != 1 || entries[0].Name() != "summary.md" {
		t.Fatalf("temporary files remain: %+v", entries)
	}
}

