		t.Fatalf("search calls = %d, want 2", searchCalls)
	}
	if fs.calls[knowledge.SearchTool] != 1 {
		t.Fatalf("real MCP searches = %d, want one plus one cache hit", fs.calls[knowledge.SearchTool])
	}
}

