package agent

import (
	"context"
	"fmt"
	"net/http"
	"os"
	"time"

	"github.com/yourusername/yourrepo/internal/artifact"
	"github.com/yourusername/yourrepo/internal/artifact/mcp"
)

func Agent() {
	// Задаем адрес MCP-сервера
	addr := os.Getenv("MCP_ADDR")
	if addr == "" {
		addr = ":8090"
	}

	// Задаем директорию для сохранения файлов
	dir := os.Getenv("OUTPUT_DIR")
	if dir == "" {
		dir = "/data/outputs"
	}

	// Создаем HTTP-сервер
	s := &http.Server{
		Addr:           addr,
		Handler:        artifact.Handler(artifact.NewStore(dir)),
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:    25 * time.Second,
		WriteTimeout:  30 * time.Second,
	}

	// Получаем контекст и функцию для остановки сервера
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)

	// Запускаем сервер и останавливаем его при получении сигнала
	go func() {
		<-ctx.Done()
		x, y := context.WithTimeout(context.Background(), 10*time.Second)
		defer y()
		_ = s.Shutdown(x)
	}()

	// Выводим сообщение о запуске сервера
	log.Printf("listening on %s", addr)

	// Запускаем сервер
	if err := s.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
		log.Fatal(err)
	}
}
