## История диалога

Web-приложение выдаёт браузеру HttpOnly session cookie и хранит последние 12 полных ходов диалога. В следующий запрос модели передаются предыдущие сообщения вместе с MCP tool calls и результатами, поэтому фразы вроде «останови созданный монитор» работают без повторного ввода ID. Кнопка «Новый диалог» очищает только историю чата; расписания и снимки MCP при этом не удаляются. История чата хранится в памяти `agent-app` и сбрасывается при его перезапуске.

Ключевые пакеты:

- `internal/mcpmulti` — агрегация каталогов и маршрутизация tool calls по нескольким MCP;
- `internal/mcpgithub`, `internal/store`, `internal/scheduler`, `internal/githubapi` — GitHub-домен;
- `internal/mcpcurrency`, `internal/currencystore`, `internal/currencyscheduler`, `internal/frankfurter`, `internal/decimal` — валютный домен;
- `internal/agent` — общий многошаговый tool-call loop;
- `internal/web` — общая панель GitHub + валюты.

func TestConversationStoreReusesCookieAndCanReset(t *testing.T) {
	store := newConversationStore()
	firstRecorder := httptest.NewRecorder()
	first := store.get(firstRecorder, httptest.NewRequest("GET", "/api/chat/history", nil))
	cookies := firstRecorder.Result().Cookies()
	if len(cookies) != 1 || cookies[0].Name != sessionCookieName {
		t.Fatalf("cookies = %#v", cookies)
	}
	secondRequest := httptest.NewRequest("GET", "/api/chat/history", nil)
	secondRequest.AddCookie(cookies[0])
	if second := store.get(httptest.NewRecorder(), secondRequest); second != first {
		t.Fatal("cookie must reuse conversation")
	}
	store.reset(httptest.NewRecorder(), secondRequest)
	if len(store.sessions) != 0 {
		t.Fatalf("sessions = %d", len(store.sessions))
	}
}

const (
	sessionCookieName    = "day18_agent_session"
	maxConversationTurns = 12
	maxConversationCount = 1024
)

func TestChatSessionPassesHistoryToNextRequestAndRestoresIt(t *testing.T) {
	chatAgent := &historyAgent{}
	handler := Handler(chatAgent, nil)

	first := httptest.NewRecorder()
	handler.ServeHTTP(first, httptest.NewRequest(http.MethodPost, "/api/chat", strings.NewReader(`{"message":"first"}`)))
	if first.Code != http.StatusOK {
		t.Fatalf("first status=%d body=%s", first.Code, first.Body.String())
	}
	cookies := first.Result().Cookies()
	if len(cookies) != 1 {
		t.Fatalf("cookies=%#v", cookies)
	}

	secondRequest := httptest.NewRequest(http.MethodPost, "/api/chat", strings.NewReader(`{"message":"second"}`))
	secondRequest.AddCookie(cookies[0])
	second := httptest.NewRecorder()
	handler.ServeHTTP(second, secondRequest)
	if second.Code != http.StatusOK {
		t.Fatalf("second status=%d body=%s", second.Code, second.Body.String())
	}
	if len(chatAgent.histories) != 2 || len(chatAgent.histories[0]) != 0 || len(chatAgent.histories[1]) != 2 || chatAgent.histories[1][0].Content != "first" {
		t.Fatalf("histories=%#v", chatAgent.histories)
	}

	historyRequest := httptest.NewRequest(http.MethodGet, "/api/chat/history", nil)
	historyRequest.AddCookie(cookies[0])
	history := httptest.NewRecorder()
	handler.ServeHTTP(history, historyRequest)
	var payload struct {
		Messages []historyMessage `json:"messages"`
	}
	if err := json.Unmarshal(history.Body.Bytes(), &payload); err != nil {
		t.Fatal(err)
	}
	if len(payload.Messages) != 4 || payload.Messages[0].Content != "first" || payload.Messages[2].Content != "second" {
		t.Fatalf("messages=%#v", payload.Messages)
	}
}

func (s *conversationStore) get(w http.ResponseWriter, r *http.Request) *conversation {
	id := ""
	if cookie, err := r.Cookie("day19_session"); err == nil {
		id = cookie.Value
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if existing := s.sessions[id]; id != "" && existing != nil {
		return existing
	}
	var raw [24]byte
	_, _ = rand.Read(raw[:])
	id = hex.EncodeToString(raw[:])
	created := &conversation{}
	s.sessions[id] = created
	http.SetCookie(w, &http.Cookie{Name: "day19_session", Value: id, Path: "/", HttpOnly: true, SameSite: http.SameSiteStrictMode, MaxAge: 86400})
	return created
}

