# Day 16 — MCP connection and tools/list

Минимальный MCP-проект на официальном Go SDK:

- `cmd/server` поднимает Streamable HTTP MCP endpoint `/mcp`;
- сервер регистрирует инструмент `server_status`;
- `cmd/client` устанавливает MCP-соединение и получает полный список tools;
- интеграционный тест проверяет handshake, версию протокола и схему tool;
- Docker-контейнер запущен на VPS и доступен только через SSH-туннель.

// ConnectAndListTools connects to endpoint and follows every tools/list page.
func ConnectAndListTools(ctx context.Context, endpoint string) (*ConnectionResult, error) {
	transport := &mcp.StreamableClientTransport{
		Endpoint: endpoint,
		HTTPClient: &http.Client{
			Timeout: 15 * time.Second,
		},
		DisableStandaloneSSE: true,
	}
	client := mcp.NewClient(
		&mcp.Implementation{Name: "day16-mcp-client", Version: ServerVersion},
		nil,
	)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return nil, fmt.Errorf("connect to MCP server: %w", err)
	}
	defer session.Close()

	result := &ConnectionResult{}
	if initialized := session.InitializeResult(); initialized != nil {
		result.ProtocolVersion = initialized.ProtocolVersion
		if initialized.ServerInfo != nil {
			result.ServerName = initialized.ServerInfo.Name
			result.ServerVersion = initialized.ServerInfo.Version
		}
	}

	params := &mcp.ListToolsParams{}
	for {
		page, err := session.ListTools(ctx, params)
		if err != nil {
			return nil, fmt.Errorf("list MCP tools: %w", err)
		}
		result.Tools = append(result.Tools, page.Tools...)
		if page.NextCursor == "" {
			break
		}
		params.Cursor = page.NextCursor
	}

	return result, nil
}

func TestConnectAndListTools(t *testing.T) {
	httpServer := httptest.NewServer(Handler())
	t.Cleanup(httpServer.Close)

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	result, err := ConnectAndListTools(ctx, httpServer.URL+"/mcp")
	if err != nil {
		t.Fatalf("ConnectAndListTools() error = %v", err)
	}
	if result.ServerName != ServerName {
		t.Fatalf("server name = %q, want %q", result.ServerName, ServerName)
	}
	if result.ProtocolVersion == "" {
		t.Fatal("protocol version is empty")
	}
	if len(result.Tools) != 1 {
		t.Fatalf("tool count = %d, want 1", len(result.Tools))
	}
	if result.Tools[0].Name != ToolName {
		t.Fatalf("tool name = %q, want %q", result.Tools[0].Name, ToolName)
	}
	if result.Tools[0].InputSchema == nil {
		t.Fatal("tool input schema is nil")
	}
}

func main() {
	defaultEndpoint := os.Getenv("MCP_ENDPOINT")
	if defaultEndpoint == "" {
		defaultEndpoint = "http://127.0.0.1:8080/mcp"
	}
	endpoint := flag.String("endpoint", defaultEndpoint, "Streamable HTTP MCP endpoint")
	flag.Parse()

	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()

	result, err := mcpdemo.ConnectAndListTools(ctx, *endpoint)
	if err != nil {
		log.Fatal(err)
	}

	fmt.Println("MCP connection established")
	fmt.Printf("Server: %s %s\n", result.ServerName, result.ServerVersion)
	fmt.Printf("Protocol: %s\n", result.ProtocolVersion)
	fmt.Printf("Tools (%d):\n", len(result.Tools))
	for _, tool := range result.Tools {
		fmt.Printf("- %s: %s\n", tool.Name, tool.Description)
	}
}

func TestMCPContractAllTools(t *testing.T) {
	wikiServer := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) { _, _ = w.Write([]byte(`{"query":{"pages":[]}}`)) }))
	defer wikiServer.Close()
	wiki := NewWikipediaClient(wikiServer.Client())
	wiki.BaseURL = wikiServer.URL
	connector := mcpclient.InMemoryConnector{Server: NewServer(wiki, NewSaver(t.TempDir()))}
	session, err := connector.Connect(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	defer session.Close()
	tools, err := session.ListTools(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	if len(tools) != 3 {
		t.Fatalf("got %d tools", len(tools))
	}
	want := map[string]bool{SearchToolName: false, SummarizeToolName: false, SaveToolName: false}
	for _, tool := range tools {
		want[tool.Name] = true
		input, ok := tool.InputSchema.(map[string]any)
		if !ok {
			t.Fatalf("%s input schema type %T", tool.Name, tool.InputSchema)
		}
		if input["additionalProperties"] != false {
			t.Errorf("%s input additionalProperties", tool.Name)
		}
		if _, exists := input["required"]; !exists || input["required"] == nil {
			t.Errorf("%s invalid required", tool.Name)
		}
		output, ok := tool.OutputSchema.(map[string]any)
		if !ok || output["additionalProperties"] != false {
			t.Errorf("%s output schema not strict", tool.Name)
		}
		if tool.Annotations == nil {
			t.Errorf("%s annotations missing", tool.Name)
		}
		annotations, ok := tool.Annotations.(*mcp.ToolAnnotations)
		if !ok {
			t.Fatalf("%s annotations type %T", tool.Name, tool.Annotations)
		}
		if annotations.OpenWorldHint == nil {
			t.Errorf("%s openWorldHint missing", tool.Name)
		} else if tool.Name == SearchToolName && !*annotations.OpenWorldHint {
			t.Error("search must be open-world")
		} else if tool.Name != SearchToolName && *annotations.OpenWorldHint {
			t.Errorf("%s must be closed-world", tool.Name)
		}
		if (tool.Name != SaveToolName) != annotations.ReadOnlyHint {
			t.Errorf("%s readOnlyHint=%v", tool.Name, annotations.ReadOnlyHint)
		}
		assertStrictObjects(t, tool.Name+" input", input)
		assertStrictObjects(t, tool.Name+" output", output)
	}
	for name, found := range want {
		if !found {
			t.Errorf("missing %s", name)
		}
	}
	search, err := session.CallTool(context.Background(), SearchToolName, map[string]any{"query": "x", "limit": 1})
	if err != nil || search.IsError {
		t.Fatalf("search call: %+v %v", search, err)
	}
	summary, err := session.CallTool(context.Background(), SummarizeToolName, map[string]any{"query": "x", "documents": []any{}, "max_sentences": 1})
	if err != nil || summary.IsError {
		t.Fatalf("summary call: %+v %v", summary, err)
	}
	saved, err := session.CallTool(context.Background(), SaveToolName, map[string]any{"filename": "x.md", "content": "summary", "sources": []any{}, "query": "x"})
	if err != nil || saved.IsError {
		t.Fatalf("save call: %+v %v", saved, err)
	}
}

